1	import { SQUAWK_TERMINAL_STATUSES } from '@/lib/maintenance/status-constants';
2	
3	export interface CanonicalSquawkRow {
4	  status?: string | null;
5	}
6	
7	const TERMINAL_STATUSES = new Set(
8	  SQUAWK_TERMINAL_STATUSES.map((status) => status.toLowerCase()),
9	);
10	
11	export function countActiveCanonicalSquawks(
12	  squawks: CanonicalSquawkRow[],
13	): number {
14	  return squawks.filter((squawk) => {
15	    const status = (squawk.status ?? '').toLowerCase();
16	    return !TERMINAL_STATUSES.has(status);
17	  }).length;
18	}
