1	import { KV_SQUAWK_TERMINAL_STATUSES } from '@/lib/maintenance/status-constants';
2	
3	type Metadata = Record<string, unknown>;
4	
5	export interface InspectionRecordLike {
6	  type?: string | null;
7	  status?: string | null;
8	  dueDate?: Date | string | null;
9	  metadata?: unknown;
10	}
11	
12	export interface InspectionEquipmentMeters {
13	  status?: string | null;
14	  hobbsTime?: number | string | null;
15	  tachTime?: number | string | null;
16	}
17	
18	const GROUNDING_INSPECTION_PATTERNS = [
19	  'annual',
20	  '100-hour',
21	  '100 hour',
22	  'progressive',
23	  'elt',
24	  'altimeter',
25	  'transponder',
26	  'pitot',
27	  'static',
28	  'engine overhaul',
29	  'prop overhaul',
30	  'magneto',
31	  'ad compliance',
32	];
33	
34	const NON_OVERRIDABLE_STATUSES = new Set(['inactive', 'retired']);
35	
36	function metadataOf(record: InspectionRecordLike): Metadata {
37	  return record.metadata &&
38	    typeof record.metadata === 'object' &&
39	    !Array.isArray(record.metadata)
40	    ? (record.metadata as Metadata)
41	    : {};
42	}
43	
44	function readString(value: unknown): string | null {
45	  return typeof value === 'string' && value.trim() ? value.trim() : null;
46	}
47	
48	function readNumber(value: unknown): number | null {
49	  if (typeof value === 'number' && Number.isFinite(value)) return value;
50	  if (typeof value === 'string' && value.trim()) {
51	    const parsed = Number(value);
52	    return Number.isFinite(parsed) ? parsed : null;
53	  }
54	  return null;
55	}
56	
57	function readDate(value: unknown): Date | null {
58	  if (value instanceof Date && !Number.isNaN(value.getTime())) return value;
59	  if (typeof value === 'string' && value.trim()) {
60	    const trimmed = value.trim();
61	    const parsed = /^\d{4}-\d{2}-\d{2}$/.test(trimmed)
62	      ? new Date(`${trimmed}T12:00:00`)
63	      : new Date(trimmed);
64	    return Number.isNaN(parsed.getTime()) ? null : parsed;
65	  }
66	  return null;
67	}
68	
69	function startOfDay(date: Date): Date {
70	  const copy = new Date(date);
71	  copy.setHours(0, 0, 0, 0);
72	  return copy;
73	}
74	
75	function isTerminalStatus(status: unknown): boolean {
76	  const lower = readString(status)?.toLowerCase();
77	  if (!lower) return false;
78	  return (
79	    KV_SQUAWK_TERMINAL_STATUSES.includes(
80	      lower as (typeof KV_SQUAWK_TERMINAL_STATUSES)[number],
81	    ) || lower === 'complete'
82	  );
83	}
84	
85	function readInspectionType(record: InspectionRecordLike): string | null {
86	  const meta = metadataOf(record);
87	  return (
88	    readString(meta.inspectionType) ??
89	    readString(meta.title) ??
90	    readString(meta.name)
91	  );
92	}
93	
94	function readMeterType(record: InspectionRecordLike): 'hobbs' | 'tach' {
95	  const meterType = readString(metadataOf(record).meterType)?.toLowerCase();
96	  return meterType === 'tach' ? 'tach' : 'hobbs';
97	}
98	
99	function currentMeterHours(
100	  equipment: InspectionEquipmentMeters,
101	  meterType: 'hobbs' | 'tach',
102	): number | null {
103	  return meterType === 'tach'
104	    ? readNumber(equipment.tachTime)
105	    : readNumber(equipment.hobbsTime);
106	}
107	
108	function hasOverdueProgressivePhase(
109	  record: InspectionRecordLike,
110	  currentMeter: number | null,
111	): boolean {
112	  if (currentMeter === null) return false;
113	  const phases = metadataOf(record).progressivePhases;
114	  if (!Array.isArray(phases)) return false;
115	  return phases.some((phase) => {
116	    if (!phase || typeof phase !== 'object') return false;
117	    const phaseRecord = phase as Metadata;
118	    const phaseStatus = readString(phaseRecord.status)?.toLowerCase();
119	    if (phaseStatus === 'completed' || phaseStatus === 'complete') return false;
120	    const dueAtHours = readNumber(phaseRecord.dueAtHours);
121	    return dueAtHours !== null && currentMeter >= dueAtHours;
122	  });
123	}
124	
125	export function isGroundingInspectionType(inspectionType?: string | null) {
126	  if (!inspectionType) return false;
127	  const lower = inspectionType.toLowerCase();
128	  return GROUNDING_INSPECTION_PATTERNS.some((pattern) =>
129	    lower.includes(pattern),
130	  );
131	}
132	
133	export function isOverdueGroundingInspection(
134	  record: InspectionRecordLike,
135	  equipment: InspectionEquipmentMeters,
136	  now = new Date(),
137	): boolean {
138	  if (record.type !== 'inspection') return false;
139	  if (isTerminalStatus(record.status)) return false;
140	
141	  const meta = metadataOf(record);
142	  const inspectionType = readInspectionType(record);
143	  const groundsAircraft =
144	    meta.groundAircraft === true || isGroundingInspectionType(inspectionType);
145	  if (!groundsAircraft) return false;
146	
147	  const meterType = readMeterType(record);
148	  const currentMeter = currentMeterHours(equipment, meterType);
149	  const dueAtHours = readNumber(meta.dueAtHours);
150	  if (dueAtHours !== null && currentMeter !== null) {
151	    return currentMeter >= dueAtHours;
152	  }
153	
154	  if (hasOverdueProgressivePhase(record, currentMeter)) return true;
155	
156	  const dueDate = readDate(record.dueDate ?? meta.dueDate);
157	  if (dueDate) return startOfDay(now) > startOfDay(dueDate);
158	
159	  return readString(record.status)?.toLowerCase() === 'overdue';
160	}
161	
162	export function hasOverdueGroundingInspection(
163	  records: InspectionRecordLike[],
164	  equipment: InspectionEquipmentMeters,
165	  now = new Date(),
166	): boolean {
167	  return records.some((record) =>
168	    isOverdueGroundingInspection(record, equipment, now),
169	  );
170	}
171	
172	export function deriveEffectiveEquipmentStatus(
173	  status: string | null | undefined,
174	  hasGroundingInspectionOverdue: boolean,
175	): string {
176	  const currentStatus = status ?? 'Available';
177	  if (!hasGroundingInspectionOverdue) return currentStatus;
178	  return NON_OVERRIDABLE_STATUSES.has(currentStatus.toLowerCase())
179	    ? currentStatus
180	    : 'Grounded';
181	}
