1	import { countActiveCanonicalSquawks } from '@/lib/maintenance/canonical-squawks';
2	import { KV_SQUAWK_TERMINAL_STATUSES } from '@/lib/maintenance/status-constants';
3	
4	type EquipmentRow = {
5	  id: string;
6	  hobbsTime?: number | string | null;
7	  tachTime?: number | string | null;
8	  totalHours?: number | string | null;
9	};
10	
11	type MaintenanceRow = {
12	  equipmentId: string;
13	  type?: string | null;
14	  status?: string | null;
15	  dueDate?: Date | string | null;
16	  metadata?: unknown;
17	};
18	
19	type SquawkRow = {
20	  equipmentId: string;
21	  status?: string | null;
22	};
23	
24	type VorCheckRow = {
25	  aircraftId: string;
26	  checkDate: Date | string;
27	  status?: string | null;
28	  withinTolerance?: boolean | null;
29	};
30	
31	export type EquipmentListEnrichment = {
32	  squawks: number;
33	  nextService: string;
34	  vorCurrencyStatus: 'current' | 'expired' | 'no_checks';
35	  vorDaysUntilExpiry: number | null;
36	};
37	
38	const TERMINAL_MAINTENANCE_STATUSES = new Set<string>(
39	  KV_SQUAWK_TERMINAL_STATUSES,
40	);
41	
42	function metadataOf(row: MaintenanceRow): Record<string, unknown> {
43	  return row.metadata &&
44	    typeof row.metadata === 'object' &&
45	    !Array.isArray(row.metadata)
46	    ? (row.metadata as Record<string, unknown>)
47	    : {};
48	}
49	
50	function finiteNumber(value: unknown): number | null {
51	  if (typeof value === 'number' && Number.isFinite(value)) return value;
52	  if (typeof value === 'string' && value.trim()) {
53	    const parsed = Number(value);
54	    return Number.isFinite(parsed) ? parsed : null;
55	  }
56	  return null;
57	}
58	
59	function validDate(value: unknown): Date | null {
60	  if (value instanceof Date) {
61	    return Number.isNaN(value.getTime()) ? null : value;
62	  }
63	  if (typeof value !== 'string' || !value.trim()) return null;
64	  const parsed = new Date(value);
65	  return Number.isNaN(parsed.getTime()) ? null : parsed;
66	}
67	
68	function maintenanceDueDate(row: MaintenanceRow): Date | null {
69	  return validDate(row.dueDate ?? metadataOf(row).dueDate);
70	}
71	
72	function isScheduledInspection(row: MaintenanceRow): boolean {
73	  return (
74	    row.type === 'inspection' &&
75	    !TERMINAL_MAINTENANCE_STATUSES.has((row.status ?? '').toLowerCase())
76	  );
77	}
78	
79	function computeNextService(
80	  equipment: EquipmentRow,
81	  maintenanceRows: MaintenanceRow[],
82	): string {
83	  const scheduled = maintenanceRows.filter(isScheduledInspection);
84	  if (scheduled.length === 0) return 'Not scheduled';
85	
86	  const withDates = scheduled
87	    .map((row) => ({ row, dueDate: maintenanceDueDate(row) }))
88	    .filter(
89	      (entry): entry is { row: MaintenanceRow; dueDate: Date } =>
90	        entry.dueDate !== null,
91	    )
92	    .sort((a, b) => a.dueDate.getTime() - b.dueDate.getTime());
93	
94	  if (withDates.length > 0) {
95	    return withDates[0].dueDate.toLocaleDateString('en-US', {
96	      month: 'short',
97	      day: 'numeric',
98	      timeZone: 'UTC',
99	    });
100	  }
101	
102	  const withHours = scheduled
103	    .map((row) => {
104	      const metadata = metadataOf(row);
105	      return {
106	        dueAtHours: finiteNumber(metadata.dueAtHours),
107	        meterType: metadata.meterType === 'tach' ? 'tach' : 'hobbs',
108	      };
109	    })
110	    .filter(
111	      (
112	        entry,
113	      ): entry is {
114	        dueAtHours: number;
115	        meterType: 'tach' | 'hobbs';
116	      } => entry.dueAtHours !== null && entry.dueAtHours > 0,
117	    );
118	
119	  if (withHours.length === 0) return 'Scheduled';
120	
121	  const hobbs =
122	    finiteNumber(equipment.hobbsTime) ||
123	    finiteNumber(equipment.totalHours) ||
124	    0;
125	  const tach = finiteNumber(equipment.tachTime) || 0;
126	  const minimumRemaining = Math.min(
127	    ...withHours.map(
128	      ({ dueAtHours, meterType }) =>
129	        dueAtHours - (meterType === 'tach' ? tach : hobbs),
130	    ),
131	  );
132	
133	  return minimumRemaining <= 0
134	    ? 'Overdue'
135	    : `In ${Math.round(minimumRemaining)} hrs`;
136	}
137	
138	function isoDate(value: Date | string): string | null {
139	  if (typeof value === 'string') {
140	    const match = value.match(/^\d{4}-\d{2}-\d{2}/);
141	    if (match) return match[0];
142	  }
143	  const date = validDate(value);
144	  return date ? date.toISOString().slice(0, 10) : null;
145	}
146	
147	function daysBetweenUtcDates(fromIsoDate: string, toDate: Date): number {
148	  const from = new Date(`${fromIsoDate}T00:00:00.000Z`);
149	  const to = new Date(
150	    Date.UTC(
151	      toDate.getUTCFullYear(),
152	      toDate.getUTCMonth(),
153	      toDate.getUTCDate(),
154	    ),
155	  );
156	  return Math.floor((to.getTime() - from.getTime()) / 86_400_000);
157	}
158	
159	function computeVorCurrency(
160	  rows: VorCheckRow[],
161	  now: Date,
162	): Pick<EquipmentListEnrichment, 'vorCurrencyStatus' | 'vorDaysUntilExpiry'> {
163	  const activeRows = rows.filter(
164	    (row) => (row.status ?? 'active') === 'active',
165	  );
166	  if (activeRows.length === 0) {
167	    return {
168	      vorCurrencyStatus: 'no_checks',
169	      vorDaysUntilExpiry: null,
170	    };
171	  }
172	
173	  const lastPassingDate = activeRows
174	    .filter((row) => row.withinTolerance === true)
175	    .map((row) => isoDate(row.checkDate))
176	    .filter((date): date is string => date !== null)
177	    .sort((a, b) => b.localeCompare(a))[0];
178	
179	  if (!lastPassingDate) {
180	    return {
181	      vorCurrencyStatus: 'expired',
182	      vorDaysUntilExpiry: null,
183	    };
184	  }
185	
186	  const daysUntilExpiry = 30 - daysBetweenUtcDates(lastPassingDate, now);
187	  return {
188	    vorCurrencyStatus: daysUntilExpiry >= 0 ? 'current' : 'expired',
189	    vorDaysUntilExpiry: daysUntilExpiry,
190	  };
191	}
192	
193	function groupByEquipmentId<T extends { equipmentId: string }>(
194	  rows: T[],
195	): Map<string, T[]> {
196	  const grouped = new Map<string, T[]>();
197	  for (const row of rows) {
198	    const list = grouped.get(row.equipmentId) ?? [];
199	    list.push(row);
200	    grouped.set(row.equipmentId, list);
201	  }
202	  return grouped;
203	}
204	
205	export function buildEquipmentListEnrichment(
206	  equipmentRows: EquipmentRow[],
207	  maintenanceRows: MaintenanceRow[],
208	  squawkRows: SquawkRow[],
209	  vorCheckRows: VorCheckRow[],
210	  now = new Date(),
211	): Map<string, EquipmentListEnrichment> {
212	  const maintenanceByEquipment = groupByEquipmentId(maintenanceRows);
213	  const squawksByEquipment = groupByEquipmentId(squawkRows);
214	  const vorChecksByEquipment = groupByEquipmentId(
215	    vorCheckRows.map((row) => ({
216	      ...row,
217	      equipmentId: row.aircraftId,
218	    })),
219	  );
220	
221	  return new Map(
222	    equipmentRows.map((equipment) => {
223	      const vorCurrency = computeVorCurrency(
224	        vorChecksByEquipment.get(equipment.id) ?? [],
225	        now,
226	      );
227	      return [
228	        equipment.id,
229	        {
230	          squawks: countActiveCanonicalSquawks(
231	            squawksByEquipment.get(equipment.id) ?? [],
232	          ),
233	          nextService: computeNextService(
234	            equipment,
235	            maintenanceByEquipment.get(equipment.id) ?? [],
236	          ),
237	          ...vorCurrency,
238	        },
239	      ];
240	    }),
241	  );
242	}
