1	/**
2	 * Work Order Auto-Creation Library
3	 *
4	 * Implements M-09 Squawk-to-Work-Order Pipeline + M-05 Automation Rules.
5	 *
6	 * Handles:
7	 *   - Squawk → Work Order (called on squawk save in routes-locations.ts)
8	 *   - Inspection approaching threshold → Work Order (called by cron every 15 min)
9	 *   - Deduplication: never creates >1 open WO for the same squawk/inspection
10	 *   - In-app notifications to maintenance staff + admin on auto-creation
11	 */
12	
13	import { db } from '@/lib/db';
14	import { safeErrorMessage } from '@/lib/safe-error-message';
15	import * as schema from '@/lib/schema';
16	import { and, desc, eq, inArray, isNull, not } from 'drizzle-orm';
17	
18	const DONE_STATUSES = ['complete', 'closed', 'voided'] as const;
19	
20	// ─── Severity → WO Priority mapping ─────────────────────────────────────────
21	function severityToPriority(
22	  severity: string | null | undefined,
23	): 'aog' | 'high' | 'normal' | 'low' {
24	  switch ((severity ?? '').toLowerCase()) {
25	    case 'grounding':
26	    case 'critical':
27	      return 'aog';
28	    case 'major':
29	      return 'high';
30	    default:
31	      return 'normal';
32	  }
33	}
34	
35	// ─── Inspection type → WO type mapping ───────────────────────────────────────
36	function inspectionTypeToWoType(
37	  inspectionType: string,
38	): '100hr' | 'annual' | 'elt' | 'altimeter_transponder' {
39	  const lower = inspectionType.toLowerCase();
40	  if (lower.includes('100-hour') || lower.includes('100 hour')) return '100hr';
41	  if (lower.includes('annual')) return 'annual';
42	  if (lower.includes('elt')) return 'elt';
43	  return 'altimeter_transponder';
44	}
45	
46	// ─── Regulatory references by inspection type ────────────────────────────────
47	const REGULATORY_REFS: Record<string, string> = {
48	  '100hr': 'FAR 91.409(b)',
49	  annual: 'FAR 91.409(a)',
50	  elt: 'FAR 91.207',
51	  altimeter_transponder: 'FAR 91.411 / FAR 91.413',
52	};
53	
54	// ─── Generate sequential WO number ───────────────────────────────────────────
55	async function generateWorkOrderNumber(orgId: string): Promise<string> {
56	  const [last] = await db
57	    .select({ workOrderNumber: schema.workOrders.workOrderNumber })
58	    .from(schema.workOrders)
59	    .where(eq(schema.workOrders.flightSchoolId, orgId))
60	    .orderBy(desc(schema.workOrders.createdAt))
61	    .limit(1);
62	
63	  const year = new Date().getFullYear();
64	  let seq = 1;
65	  if (last?.workOrderNumber) {
66	    const m = last.workOrderNumber.match(/(\d+)$/);
67	    if (m) seq = Number.parseInt(m[1], 10) + 1;
68	  }
69	  // Ensure uniqueness under concurrent agent runs by re-checking at insert time
70	  return `WO-${year}-${String(seq).padStart(4, '0')}`;
71	}
72	
73	// ─── Create location notification ────────────────────────────────────────────
74	async function createWorkOrderNotification(
75	  orgId: string,
76	  locationId: string,
77	  title: string,
78	  body: string,
79	  workOrderId: string,
80	  workOrderNumber: string,
81	): Promise<void> {
82	  try {
83	    await db.insert(schema.locationNotifications).values({
84	      flightSchoolId: orgId,
85	      locationId,
86	      title,
87	      body,
88	      read: false,
89	      metadata: {
90	        workOrderId,
91	        workOrderNumber,
92	        type: 'work_order_auto_created',
93	      } as never,
94	    });
95	  } catch (err) {
96	    console.error(
97	      '[WO-AutoCreate] Failed to create notification:',
98	      safeErrorMessage(err),
99	    );
100	  }
101	}
102	
103	// ─── SQUAWK → Work Order ─────────────────────────────────────────────────────
104	
105	export interface SquawkInput {
106	  /** UUID of the squawk record — used as sourceId on the WO for reliable dedup */
107	  id?: string;
108	  title: string;
109	  description?: string | null;
110	  notes?: string | null;
111	  severity?: string | null;
112	  priority?: string | null;
113	  groundAircraft?: boolean;
114	}
115	
116	export interface AutoCreateResult {
117	  created: boolean;
118	  workOrderId?: string;
119	  workOrderNumber?: string;
120	  reason?: string;
121	}
122	
123	/**
124	 * Auto-create a work order from a newly filed squawk.
125	 * Idempotent: skips creation if an open WO already exists for this squawk
126	 * (matched by sourceType='squawk', equipmentId, and title).
127	 */
128	export async function autoCreateWorkOrderFromSquawk(
129	  orgId: string,
130	  locationId: string,
131	  equipmentId: string,
132	  squawk: SquawkInput,
133	): Promise<AutoCreateResult> {
134	  try {
135	    const squawkTitle = squawk.title?.trim();
136	    if (!squawkTitle) {
137	      return { created: false, reason: 'squawk has no title' };
138	    }
139	
140	    // Deduplication: prefer matching by squawk UUID (sourceId) when available,
141	    // fall back to title match for calls from routes-locations.ts legacy path.
142	    const existing = await db
143	      .select({
144	        id: schema.workOrders.id,
145	        workOrderNumber: schema.workOrders.workOrderNumber,
146	      })
147	      .from(schema.workOrders)
148	      .where(
149	        and(
150	          eq(schema.workOrders.flightSchoolId, orgId),
151	          eq(schema.workOrders.equipmentId, equipmentId),
152	          eq(schema.workOrders.sourceType, 'squawk'),
153	          squawk.id
154	            ? eq(schema.workOrders.sourceId, squawk.id)
155	            : eq(schema.workOrders.title, squawkTitle),
156	          not(inArray(schema.workOrders.status, [...DONE_STATUSES])),
157	        ),
158	      )
159	      .limit(1);
160	
161	    if (existing.length > 0) {
162	      return {
163	        created: false,
164	        reason: 'open WO already exists for this squawk',
165	        workOrderId: existing[0].id,
166	        workOrderNumber: existing[0].workOrderNumber,
167	      };
168	    }
169	
170	    const priority = severityToPriority(squawk.severity ?? squawk.priority);
171	    const isAog = priority === 'aog' || squawk.groundAircraft === true;
172	    const woType = isAog ? 'aog' : 'unscheduled_repair';
173	
174	    const description =
175	      squawk.description?.trim() ||
176	      squawk.notes?.trim() ||
177	      `Auto-created from squawk: ${squawkTitle}`;
178	
179	    // Retry loop: re-query last WO number on each attempt to handle concurrent
180	    // creation collisions (PostgreSQL 23505 unique_violation on work_order_number).
181	    let created: typeof schema.workOrders.$inferSelect | undefined;
182	    for (let attempt = 1; attempt <= 5; attempt++) {
183	      const workOrderNumber = await generateWorkOrderNumber(orgId);
184	      try {
185	        [created] = await db
186	          .insert(schema.workOrders)
187	          .values({
188	            flightSchoolId: orgId,
189	            locationId,
190	            equipmentId,
191	            workOrderNumber,
192	            title: squawkTitle,
193	            type: woType,
194	            priority,
195	            status: 'draft',
196	            description,
197	            grounded: isAog,
198	            sourceType: 'squawk',
199	            sourceId: squawk.id ?? undefined,
200	            sourceLabel: squawkTitle,
201	          })
202	          .returning();
203	        break; // INSERT succeeded
204	      } catch (insertErr) {
205	        const code =
206	          typeof insertErr === 'object' && insertErr !== null
207	            ? (insertErr as Record<string, unknown>).code
208	            : undefined;
209	        if (code === '23505' && attempt < 5) continue;
210	        throw insertErr;
211	      }
212	    }
213	
214	    if (!created) {
215	      return { created: false, reason: 'DB insert returned no row' };
216	    }
217	
218	    // Link the originating discrepancy (created alongside the squawk) to this WO.
219	    // The discrepancy has linkedSquawkId = squawk.id but linkedWorkOrderId was never
