269	// ─── INSPECTION → Work Order ─────────────────────────────────────────────────
270	
271	export interface InspectionInput {
272	  id: string;
273	  inspectionType: string;
274	  dueDate?: Date | null;
275	  dueAtHours?: number | null;
276	  currentMeterHours?: number | null;
277	  meterType?: string | null;
278	  farReference?: string | null;
279	  tailNumber?: string | null;
280	  isOverdue?: boolean;
281	}
282	
283	/**
284	 * Auto-create a work order for an inspection.
285	 *
286	 * As of 2026-05-11 (Asana 1214678247527059) the cron only calls this with
287	 * `isOverdue=true` — pre-staging draft WOs for upcoming-but-not-yet-due
288	 * inspections was polluting the queue and corrupting the AOG signal.
289	 * Callers that pass `isOverdue=false` will still create a Normal/draft WO,
290	 * but the cron no longer takes that path.
291	 *
292	 * Idempotent: skips if an open WO already exists for this inspection type
293	 * on this aircraft. When an existing WO is found and `isOverdue=true`,
294	 * its priority/grounded fields are escalated to AOG.
295	 */
296	export async function autoCreateWorkOrderFromInspection(
297	  orgId: string,
298	  locationId: string,
299	  equipmentId: string,
300	  inspection: InspectionInput,
301	): Promise<AutoCreateResult> {
302	  try {
303	    const woType = inspectionTypeToWoType(inspection.inspectionType);
304	    const isOverdue = inspection.isOverdue ?? false;
305	    const priority = isOverdue ? 'aog' : 'normal';
306	    const tailNumber = inspection.tailNumber ?? 'Unknown Aircraft';
307	
308	    const title = `${inspection.inspectionType} — ${tailNumber}`;
309	
310	    // Deduplication: one open WO per inspection type per aircraft
311	    const existing = await db
312	      .select({
313	        id: schema.workOrders.id,
314	        workOrderNumber: schema.workOrders.workOrderNumber,
315	      })
316	      .from(schema.workOrders)
317	      .where(
318	        and(
319	          eq(schema.workOrders.flightSchoolId, orgId),
320	          eq(schema.workOrders.equipmentId, equipmentId),
321	          eq(schema.workOrders.sourceType, 'inspection'),
322	          eq(schema.workOrders.type, woType),
323	          not(inArray(schema.workOrders.status, [...DONE_STATUSES])),
324	        ),
325	      )
326	      .limit(1);
327	
328	    if (existing.length > 0) {
329	      // Check if priority should escalate (approaching → overdue)
330	      if (isOverdue && existing[0]) {
331	        await db
332	          .update(schema.workOrders)
333	          .set({ priority: 'aog', grounded: true })
334	          .where(eq(schema.workOrders.id, existing[0].id));
335	      }
336	      return {
337	        created: false,
338	        reason: 'open WO already exists for this inspection type',
339	        workOrderId: existing[0].id,
340	        workOrderNumber: existing[0].workOrderNumber,
341	      };
342	    }
343	
344	    // Build auto-generated description
345	    let description = '';
346	    if (
347	      woType === '100hr' &&
348	      inspection.dueAtHours !== null &&
349	      inspection.currentMeterHours !== null
350	    ) {
351	      const remaining =
352	        (inspection.dueAtHours ?? 0) - (inspection.currentMeterHours ?? 0);
353	      const meterLabel =
354	        inspection.meterType === 'tach' ? 'tach hrs' : 'Hobbs hrs';
355	      description =
356	        `FAR ${inspection.farReference ?? REGULATORY_REFS[woType]} required 100-hour inspection. ` +
357	        `Due at ${inspection.dueAtHours} ${meterLabel}. ` +
358	        `Currently at ${inspection.currentMeterHours} hrs. ` +
359	        `${Math.max(0, remaining).toFixed(1)} hours remaining.`;
360	    } else if (inspection.dueDate) {
361	      const daysUntil = Math.ceil(
362	        (inspection.dueDate.getTime() - Date.now()) / (24 * 60 * 60 * 1000),
363	      );
364	      description =
365	        `FAR ${inspection.farReference ?? REGULATORY_REFS[woType] ?? ''} required inspection. ` +
366	        `Due: ${inspection.dueDate.toLocaleDateString('en-US')}. ` +
367	        `${daysUntil < 0 ? `${Math.abs(daysUntil)} days overdue.` : `${daysUntil} days remaining.`}`;
368	    } else {
369	      description = `Auto-created for ${inspection.inspectionType} on ${tailNumber}.`;
370	    }
371	
372	    // Retry loop: re-query last WO number on each attempt to handle concurrent
373	    // creation collisions (PostgreSQL 23505 unique_violation on work_order_number).
374	    let created: typeof schema.workOrders.$inferSelect | undefined;
375	    for (let attempt = 1; attempt <= 5; attempt++) {
376	      const workOrderNumber = await generateWorkOrderNumber(orgId);
377	      try {
378	        [created] = await db
379	          .insert(schema.workOrders)
380	          .values({
381	            flightSchoolId: orgId,
382	            locationId,
383	            equipmentId,
384	            workOrderNumber,
385	            title,
386	            type: woType,
387	            priority,
388	            status: 'draft',
389	            description,
390	            grounded: isOverdue,
391	            dueDate: inspection.dueDate ?? undefined,
392	            regulatoryRefs:
393	              inspection.farReference ?? REGULATORY_REFS[woType] ?? undefined,
394	            sourceType: 'inspection',
395	            sourceId: inspection.id,
396	            sourceLabel: inspection.inspectionType,
397	          })
398	          .returning();
399	        break; // INSERT succeeded
400	      } catch (insertErr) {
401	        const code =
402	          typeof insertErr === 'object' && insertErr !== null
403	            ? (insertErr as Record<string, unknown>).code
404	            : undefined;
405	        if (code === '23505' && attempt < 5) continue;
406	        throw insertErr;
407	      }
408	    }
409	
410	    if (!created) {
411	      return { created: false, reason: 'DB insert returned no row' };
412	    }
413	
414	    // In-app notification
415	    const notifTitle = isOverdue
416	      ? `⚠️ OVERDUE Work Order Auto-Created — ${title}`
417	      : `🔧 Inspection WO Auto-Created — ${title}`;
418	    await createWorkOrderNotification(
419	      orgId,
420	      locationId,
421	      notifTitle,
422	      `${created.workOrderNumber}: ${title} · Draft`,
423	      created.id,
424	      created.workOrderNumber,
425	    );
426	
427	    console.info(
428	      `[WO-AutoCreate] Created ${created.workOrderNumber} from ${inspection.inspectionType} for equipment ${equipmentId}`,
429	    );
430	
431	    return {
432	      created: true,
433	      workOrderId: created.id,
434	      workOrderNumber: created.workOrderNumber,
435	    };
436	  } catch (err) {
437	    console.error(
438	      '[WO-AutoCreate] inspection→WO failed:',
439	      safeErrorMessage(err),
440	    );
441	    return { created: false, reason: safeErrorMessage(err) };
442	  }
443	}
