374	export function groupWorkOrders(
375	  workOrders: WorkOrder[],
376	): Record<SectionKey, WorkOrder[]> {
377	  const groups: Record<SectionKey, WorkOrder[]> = {
378	    aog: [],
379	    in_progress: [],
380	    awaiting_parts: [],
381	    pending_signoff: [],
382	    open: [],
383	    complete: [],
384	    draft: [],
385	    cancelled: [],
386	  };
387	  for (const wo of workOrders) {
388	    if (wo.priority === 'aog' && !AOG_EXCLUDED_STATUSES.has(wo.status)) {
389	      groups.aog.push(wo);
390	    } else if (wo.status === 'pending_inspection') {
391	      groups.pending_signoff.push(wo);
392	    } else if (wo.status === 'closed' || wo.status === 'voided') {
393	      groups.cancelled.push(wo);
394	    } else if (wo.status === 'scheduled') {
395	      groups.open.push(wo);
396	    } else if (wo.status in groups) {
397	      (groups as Record<string, WorkOrder[]>)[wo.status].push(wo);
398	    }
399	  }
400	  return groups;
401	}
